import {lessons,phrases,scenarios,pronunciation,phases} from './content.mjs';
import {STORAGE_KEY,dayKey,initialState,validateState,schedule,dueCards,streak,daysUntil,compareSpeech,logActivity,validDay} from './core.mjs';

const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z"/>',book:'<path d="M12 5v16m0-16C8 2 3 4 3 4v15s5-2 9 2c4-4 9-2 9-2V4s-5-2-9 1Z"/>',cards:'<rect x="5" y="5" width="15" height="16" rx="2"/><path d="M16 2H4a2 2 0 0 0-2 2v13m7-8h7m-7 4h5"/>',mic:'<rect x="9" y="2" width="6" height="12" rx="3"/><path d="M5 10v2a7 7 0 0 0 14 0v-2m-7 9v3m-4 0h8"/>',chat:'<path d="M21 11a9 9 0 0 1-9 9H3l1-5A9 9 0 1 1 21 11Z"/><path d="M8 10h8m-8 4h5"/>',chart:'<path d="M3 3v18h18M8 16v-5m5 5V7m5 9V4"/>',settings:'<path d="m9 3 1-1h4l1 3 3 1 3 1-1 4 1 2-1 4-3 1-2 3h-4l-2-3-3-1-3-1 1-4-1-2 1-4 3-1Z"/><circle cx="12" cy="12" r="3"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',back:'<path d="M20 12H4m6-6-6 6 6 6"/>',volume:'<path d="m11 4-6 5H2v6h3l6 5Zm4 4a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v6l4 2"/>',flame:'<path d="M12 2c1 5-4 7-2 10 3-1 4-4 4-4 5 4 7 12-2 14-9-2-8-10-4-14-1 3 0 4 0 4-1-5 4-7 4-10Z"/>',check:'<path d="m5 12 4 4L19 6"/>',search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M3 16v5h18v-5"/>',stop:'<rect x="5" y="5" width="14" height="14" rx="1"/>',play:'<path d="m8 3 13 9-13 9Z"/>',globe:'<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3c-5 5-5 13 0 18 5-5 5-13 0-18Z"/>',spark:'<path d="m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3Z"/>'};
function icon(name){return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.spark}</svg>`;}
$$('[data-icon]').forEach(n=>n.innerHTML=icon(n.dataset.icon));
const main=$('#main');let state=initialState(),storageProblem=false;
try{const s=localStorage.getItem(STORAGE_KEY);if(s)state=validateState(JSON.parse(s));}catch{storageProblem=true;}
function save(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));}catch{if(!storageProblem)toast('Device storage is unavailable. Export a backup to keep this session.');storageProblem=true;}updateChrome();}
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('visible'),4800);}
const nav=[['today','home','Today'],['lessons','book','Learn'],['review','cards','Review'],['practice','mic','Practice'],['phrases','chat','Phrasebook'],['progress','chart','Progress']];
let route='',sub='',quiz=null,review=null,speakIndex=0,speechResult=null,scenarioSession=null,recognition=null,recording=null,recordTimeout,recordUrl='',recordStream=null,voices=[],installPrompt=null,sessionSpoken=new Set();
const Recognition=window.SpeechRecognition||window.webkitSpeechRecognition;
const voiceList=()=>voices.filter(v=>/^es(?:-|_)/i.test(v.lang)||v.lang==='es');
const mexicanVoice=v=>/^es[-_]MX$/i.test(v.lang);
function selectedVoice(){return voiceList().find(v=>v.voiceURI===state.settings.voice)||voiceList().find(v=>mexicanVoice(v)&&!/(Eddy|Flo|Grandma|Grandpa|Reed|Rocko|Sandy|Shelley)/i.test(v.name))||voiceList().find(mexicanVoice);}
function loadVoices(){voices=window.speechSynthesis?.getVoices()||[];updateVoiceStatus();if(route==='settings')renderVoiceOptions();}
function updateVoiceStatus(){const v=selectedVoice();$$('[data-voice-status]').forEach(n=>{n.className=`notice ${v&&mexicanVoice(v)?'':'warn'}`;n.innerHTML=!window.speechSynthesis?'Audio playback is not available in this browser. Open Rumbo in Safari, Chrome, or Edge.':v?`${icon('volume')} <span>${esc(v.name)} · ${esc(v.lang)}${mexicanVoice(v)?' · Mexican Spanish':' · This voice uses a different Spanish accent'}. <a href="#settings">Audio settings</a></span>`:'A Mexican Spanish voice hasn’t loaded on this device. <a href="#settings">Set up your listening voice →</a>';});}
function say(text,slow=false,button=null){
 if(!window.speechSynthesis){toast('Speech playback is unavailable in this browser.');return;}
 loadVoices();const voice=selectedVoice();
 if(!voice){toast('Choose or install a Spanish (Mexico) voice in Settings & audio first.');return;}
 window.speechSynthesis.cancel();$$('.is-playing').forEach(n=>n.classList.remove('is-playing'));
 const u=new SpeechSynthesisUtterance(text);u.voice=voice;u.lang=voice.lang;u.rate=slow?.65:state.settings.rate;
 button?.classList.add('is-playing');u.onend=()=>button?.classList.remove('is-playing');u.onerror=e=>{button?.classList.remove('is-playing');if(e.error!=='interrupted'&&e.error!=='canceled')toast('The voice could not play. Check your device audio and installed voices.');};
 window.speechSynthesis.speak(u);
}
function sound(es,slow=false,label='Listen'){return `<button class="sound-btn" data-say="${encodeURIComponent(es)}" ${slow?'data-slow="true"':''} aria-label="${esc(label)}: ${esc(es)}">${icon('volume')}</button>`;}
function listenButton(es,slow=false,label='Listen'){return `<button class="btn secondary small" data-say="${encodeURIComponent(es)}" ${slow?'data-slow="true"':''}>${icon('volume')}${esc(label)}</button>`;}
function action(label,id,style='primary',extra=''){return `<button class="btn ${style}" data-action="${id}" ${extra}>${label}</button>`;}
function heading(title,subtitle='',eyebrow='YOUR SPANISH JOURNEY',side=''){return `<div class="page-intro"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1>${subtitle?`<p class="subtitle">${subtitle}</p>`:''}</div>${side}</div>`;}
function sourceNote(){return '<p class="source-note">Core lessons adapted from <em>Gramática básica del español</em>, shared by Trinia. Thank you, Trinia, for the material that started this journey. Travel dialogues and extra phrases supplement the guide. Examples focus on Mexican usage and tú, usted, and ustedes.</p>';}
function totalPoints(){return Object.values(state.activity).reduce((sum,a)=>sum+a.points,0);}
function todayMinutes(){return state.activity[dayKey()]?.minutes||0;}
function reviewedCount(){return Object.keys(state.cards).filter(id=>phrases.some(p=>p.id===id)).length;}
function completedCount(){return lessons.filter(l=>state.completed[l.id]).length;}
function nextLesson(){return lessons.find(l=>!state.completed[l.id])||lessons[0];}
function updateChrome(){const active=route==='lesson'?'lessons':route==='scenario'?'practice':route;
 $('#nav').innerHTML=nav.map(([id,i,label])=>`<a class="nav-link ${active===id?'active':''}" href="#${id}" ${active===id?'aria-current="page"':''}>${icon(i)}${label}${id==='review'?`<span class="badge">${dueCards(phrases,state).length}</span>`:''}</a>`).join('');
 $('#mobile-nav').innerHTML=nav.slice(0,5).map(([id,i,label])=>`<a class="${active===id?'active':''}" href="#${id}" ${active===id?'aria-current="page"':''}>${icon(i)}${label}</a>`).join('');
 $('#streak-chip').innerHTML=`${icon('flame')} ${streak(state.activity)} day streak`;
 $('#sidebar-trip').textContent=new Date(state.settings.trip+'T12:00:00').toLocaleDateString('en',{month:'long',year:'numeric'});
}
function tripChip(){return `<a class="trip-chip" href="#settings">🇲🇽 <strong>${daysUntil(state.settings.trip)} days</strong> to Mexico ${icon('arrow')}</a>`;}
function illustration(){return `<svg viewBox="0 0 420 350" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="An illustrated Mexican street, cactus, and sun"><defs><pattern id="lines" width="6" height="6" patternUnits="userSpaceOnUse"><path d="M0 6 6 0" stroke="#56754c" stroke-width=".5" opacity=".15"/></pattern></defs><circle cx="240" cy="117" r="77" fill="#f1d381"/><g stroke="#d4b76c" stroke-width="1.3"><path d="M240 23v-9M240 220v-9M137 117h-9M352 117h-10M166 43l-7-7M314 43l7-7"/></g><path d="M32 294c84-70 122-45 193-32 55 10 94-42 167-25v113H32Z" fill="#ccd6b6"/><path d="M196 220h137v130H196Z" fill="#d2a072"/><path d="M181 222h166v13H181Z" fill="#c88f60"/><path d="M229 217v-39h72v39" fill="#e6b587"/><path d="M219 180h92v8h-92Z" fill="#ce9669"/><path d="M256 350v-65c0-27 46-27 46 0v65" fill="#6b7e55"/><path d="M265 350v-65c0-16 28-16 28 0v65" fill="#536947"/><path d="M206 258h25v33h-25Zm111 0h12v33h-12Z" fill="#82926d"/><path d="M206 258h25v7h-25Z" fill="#627b58"/><path d="M218 258v33m-12-20h25" stroke="#e2bd94" stroke-width="2"/><path d="M244 199h10v15h-10Zm28 0h10v15h-10Z" fill="#7c8b61"/><path d="M46 350v-80h119v80" fill="#e7bf95"/><path d="M38 267h137v10H38Z" fill="#cf9b6d"/><path d="M66 293h25v35H66Zm50 0h25v35h-25Z" fill="#8d9c73"/><path d="M76 293v35m52-35v35" stroke="#e3bd91" stroke-width="2"/><g fill="#52734b"><path d="M126 350V206c0-22 25-22 25 0v144Z"/><path d="M134 274h-25c-20 0-29-13-29-30v-30c0-18 20-18 20 0v26c0 7 4 11 11 11h23Zm8-32h24c19 0 28-12 28-30v-17c0-18-20-18-20 0v16c0 6-4 10-10 10h-22Z"/></g><g stroke="#7d965e" stroke-width="1.5" fill="none"><path d="M138 202v140m-47-125v25q0 21 23 21h18m52-65v15q0 21-21 21h-14"/></g><path d="M20 350h385" stroke="#a1b18a" stroke-width="2"/><g fill="#778c5c"><path d="M349 350v-32q-22-23-9-30 15-5 14 23 11-36 23-28 9 8-12 31 18-13 23-4 5 9-25 18v22Z"/><path d="M17 350q1-30 12-29 9 1-1 29 15-22 23-14 6 7-13 14Z"/></g><g transform="rotate(9 340 71)"><rect x="291" y="41" width="87" height="96" rx="2" fill="#fcfaf0" stroke="#d7deca"/><rect x="298" y="48" width="73" height="68" fill="none" stroke="#c5cbb8" stroke-dasharray="2 2"/><text x="334" y="71" text-anchor="middle" fill="#657558" font-family="Georgia,serif" font-size="12">MÉXICO</text><path d="m323 85 10 6 12-12-7 15-2 8-4-8-8-2Z" fill="#a9b396"/><text x="334" y="127" text-anchor="middle" fill="#8b967e" font-family="sans-serif" font-size="7" letter-spacing="1.5">FEB 2027</text></g><path d="M65 113q24-10 42 4m-32-14 10 11-4 11" fill="none" stroke="#8d9e79" stroke-width="1.4"/><path d="M57 165q-10-25 12-40" fill="none" stroke="#8d9e79" stroke-width="1" stroke-dasharray="4 5"/></svg>`;}
function todayPage(){const next=nextLesson(),count=completedCount(),due=dueCards(phrases,state).length;const phrase=phrases.find(p=>/cuenta/.test(p.es))||phrases[0];const date=new Date().toLocaleDateString('en',{weekday:'long',day:'numeric',month:'long'});
 main.innerHTML=heading('Hola, future traveler.', '',date,tripChip())+`<section class="hero"><div class="hero-copy"><span class="pill"><i></i> YOUR FEBRUARY 2027 ADVENTURE</span><h2>A little Spanish.<br><em>A lot more Mexico.</em></h2><p>From your first “hola” to ordering like you belong. Build a little confidence every day.</p><a href="#lesson/${next.id}" class="btn primary">${count?'Continue your journey':'Start your first lesson'} ${icon('arrow')}</a><div class="hero-footnote">${icon('clock')} ${state.settings.goal} minutes a day. A world of difference.</div></div><div class="hero-art">${illustration()}</div></section>
 <div class="stats-row"><a href="#progress" class="stat"><span class="stat-icon">${icon('flame')}</span><div><strong>${streak(state.activity)} <span style="font-size:12px">${streak(state.activity)===1?'day':'days'}</span></strong><small>Your learning streak</small></div></a><a href="#review" class="stat"><span class="stat-icon">${icon('cards')}</span><div><strong>${reviewedCount()}</strong><small>Phrases you've reviewed</small></div></a><a href="#lessons" class="stat"><span class="stat-icon">${icon('book')}</span><div><strong>${count}<span style="font-size:12px;color:var(--muted)"> / ${lessons.length}</span></strong><small>Lessons completed</small></div></a></div>
 <section><div class="section-heading"><h2>Your daily itinerary</h2><span>Your ${state.settings.goal}-minute daily goal.</span></div><div class="daily-grid">${[[`lesson/${next.id}`,'Learn something new',next.title,'YOUR GRAMMAR GUIDE','5 min'],['review','Make it stick',`${due} phrases ready for review`,'SPACED REPETITION','5 min'],['practice','Say it out loud','Listen, repeat, feel the rhythm','MEXICAN SPANISH','5 min']].map(([url,title,desc,tag,time],i)=>`<a class="task-card" href="#${url}"><div class="task-top"><span class="task-number">0${i+1}</span><span class="task-time">${icon('clock')}${time}</span></div><h3>${title}</h3><p>${esc(desc)}</p><div class="task-bottom"><span class="task-tag">${tag}</span><span class="arrow-circle">${icon('arrow')}</span></div></a>`).join('')}</div></section>
 <div class="lower-grid"><section class="phrase-feature"><p class="eyebrow">A PHRASE TO TAKE WITH YOU</p><blockquote lang="es-MX">${esc(phrase.es)}</blockquote><p>${esc(phrase.en)}</p>${sound(phrase.es)}<a class="text-link" href="#phrases">Explore your phrasebook ${icon('arrow')}</a></section><section class="route-panel"><p class="eyebrow">SMALL STEPS, BIG ADVENTURE</p><h3>On your way to México</h3><div class="progress-track"><span style="width:${count/lessons.length*100}%"></span></div><div class="progress-label"><span>${count} of ${lessons.length} lessons complete</span><a href="#progress" class="text-link">Your progress ${icon('arrow')}</a></div><div class="route-steps">${['Get started','Find your words','Talk a little','Travel ready'].map((t,i)=>`<div class="route-step ${i===Math.min(3,Math.floor(count/lessons.length*4))?'active':''}"><span>${i+1}</span>${t}</div>`).join('')}</div></section></div>${storageProblem?'<div class="notice warn">Storage is unavailable or a saved file could not be read. Export your progress from Settings to keep a backup.</div>':''}`;
}
function lessonsPage(){main.innerHTML=heading('Small lessons. Real conversations.', 'Your grammar guide, broken into easy, practical steps.','LEARN AT YOUR PACE',`<span class="trip-chip">${completedCount()} / ${lessons.length} complete</span>`)+`<div class="lesson-list">${lessons.map((l,i)=>`<a class="lesson-card ${state.completed[l.id]?'complete':''}" href="#lesson/${l.id}"><div class="lesson-index">${state.completed[l.id]?'✓':String(i+1).padStart(2,'0')}</div><div><p class="eyebrow">${esc(l.unit)}</p><h2>${esc(l.title)}</h2><p>${esc(l.subtitle)}</p><div class="lesson-meta"><span>${l.duration} min</span><span>${l.questions.length} questions</span>${state.completed[l.id]?'<span class="completed">Completed</span>':''}</div></div></a>`).join('')}</div>`+sourceNote();}
function lessonPage(id){const l=lessons.find(l=>l.id===id);if(!l){location.hash='lessons';return;}const idx=lessons.indexOf(l);
 main.innerHTML=`<div class="lesson-body"><a class="text-link back-link" href="#lessons">${icon('back')} All lessons</a>${heading(esc(l.title),esc(l.subtitle),`LESSON ${String(idx+1).padStart(2,'0')} · ${esc(l.unit)}`)}<div class="panel">${l.explanation.map(p=>`<p>${esc(p)}</p>`).join('')}</div><section class="panel"><h2>Hear it in context</h2>${l.examples.map(e=>`<div class="example"><div><strong lang="es-MX">${esc(e.es)}</strong><p>${esc(e.en)}</p>${e.note?`<small>${esc(e.note)}</small>`:''}</div>${sound(e.es)}</div>`).join('')}</section><div data-voice-status></div><div class="panel"><h2>Ready to try it?</h2><p>A quick check helps your new words stick. Complete at least ${Math.ceil(l.questions.length*.65)} of ${l.questions.length} questions correctly to finish the lesson.</p>${action('Check understanding '+icon('arrow'),'start-quiz','primary',`data-id="${id}"`)}</div>${sourceNote()}</div>`;updateVoiceStatus();}
function renderQuiz(){const l=lessons.find(l=>l.id===quiz.id),q=l.questions[quiz.index];if(!q)return finishQuiz();main.innerHTML=`<div class="lesson-body"><a class="text-link back-link" href="#lesson/${l.id}">${icon('back')} Back to lesson</a>${heading('Put it into practice.',esc(l.title),'A QUICK CONFIDENCE CHECK')}<div class="quiz-progress"><span>Question ${quiz.index+1} of ${l.questions.length}</span><div class="progress-track"><span style="width:${quiz.index/l.questions.length*100}%"></span></div></div><section class="panel"><h2 class="quiz-question">${esc(q.prompt)}</h2><div class="quiz-options">${q.options.map((v,i)=>`<button class="quiz-option ${quiz.choice!==null?(i===q.answer?'correct':i===quiz.choice?'wrong':''):''}" data-action="quiz-answer" data-index="${i}" ${quiz.choice!==null?'disabled':''}><span>${String.fromCharCode(65+i)}</span>${esc(v)}</button>`).join('')}</div>${quiz.choice!==null?`<div class="feedback ${quiz.choice===q.answer?'':'wrong'}" role="status"><strong>${quiz.choice===q.answer?'¡Muy bien!':'Keep going — this is how you learn.'}</strong><br>${esc(q.explanation)}</div>${action(quiz.index===l.questions.length-1?'See my result':'Next question '+icon('arrow'),'quiz-next')}`:''}</section></div>`;}
function finishQuiz(){const l=lessons.find(l=>l.id===quiz.id),pass=quiz.score>=Math.ceil(l.questions.length*.65),first=!state.completed[l.id];if(pass){state.completed[l.id]={score:quiz.score,total:l.questions.length,date:dayKey()};logActivity(state,first?30:5,first?l.duration:1);save();}
 main.innerHTML=`<div class="lesson-body panel completion"><div class="big-icon">${pass?'✳':'🌱'}</div><p class="eyebrow">${pass?'ONE STEP CLOSER TO MÉXICO':'A LITTLE MORE PRACTICE'}</p><h1>${pass?'Look at you, learning Spanish.':'You’re finding your feet.'}</h1><p>${quiz.score} of ${l.questions.length} correct. ${pass?'Your lesson is complete.':'Read the examples once more, then give it another go.'}</p><div>${pass?`<a class="btn primary" href="#lesson/${nextLesson().id}">Next lesson ${icon('arrow')}</a>`:action('Try again','start-quiz','primary',`data-id="${l.id}"`)}<a class="btn secondary" href="#lessons">All lessons</a></div><p class="center-note">${pass&&first?'+30 points · Progress saved on this device':''}</p></div>`;quiz=null;}
function phrasePage(){main.innerHTML=heading('Words for wherever you wander.',`${phrases.length} useful phrases. Tap to hear them, then make them yours.`,'YOUR POCKET PHRASEBOOK')+`<div class="toolbar"><div class="search-wrap">${icon('search')}<input id="phrase-search" type="search" placeholder="Search in English or Spanish…" aria-label="Search phrases"></div><select id="phrase-category" aria-label="Filter phrases"><option value="all">All situations</option>${[...new Set(phrases.map(p=>p.category))].map(c=>`<option>${esc(c)}</option>`).join('')}</select><a class="btn secondary" href="#review">${icon('cards')} Review</a></div><div data-voice-status></div><div id="phrase-results" class="phrase-list"></div>`;filterPhrases();updateVoiceStatus();}
function filterPhrases(){const term=$('#phrase-search')?.value.toLocaleLowerCase()||'',cat=$('#phrase-category')?.value||'all';const found=phrases.filter(p=>(cat==='all'||cat===p.category)&&`${p.es} ${p.en}`.toLocaleLowerCase().includes(term));$('#phrase-results').innerHTML=found.length?found.map(p=>`<article class="phrase-card"><div><div class="category">${esc(p.category)}</div><strong lang="es-MX">${esc(p.es)}</strong><p>${esc(p.en)}</p>${p.note?`<small>${esc(p.note)}</small>`:''}</div><div class="phrase-actions">${sound(p.es)}<a class="sound-btn" href="#practice/${p.id}" aria-label="Practice this phrase: ${esc(p.es)}">${icon('mic')}</a></div></article>`).join(''):'<div class="empty">No phrases found. Try another word or situation.</div>';}
function reviewPage(){const due=dueCards(phrases,state),seen=reviewedCount(),learning=Object.values(state.cards).filter(c=>c.due<=Date.now()).length;
 main.innerHTML=heading('A few words, remembered.', 'Recall a phrase, reveal the answer, then rate how it felt.','SPACED REVIEW',`<span class="trip-chip">${due.length} ready</span>`)+`<div class="review-shell"><div class="panel completion"><div class="big-icon">${icon('cards')}</div><h2 class="completion-title">${due.length?'Keep your Spanish close.':'You’re all caught up.'}</h2><p>${due.length?`${learning} previously reviewed · ${phrases.length-seen} new phrases`:'Your next reviews will appear when they’re due.'}</p><p class="center-note">${due.length?'A short session of up to 10 cards. New phrases join your schedule as you review them.':'Come back tomorrow, or explore a lesson now.'}</p>${due.length?action('Start 10-card review '+icon('arrow'),'start-review'):'<a class="btn primary" href="#lessons">Explore lessons</a>'}</div><div class="notice">Say the Spanish out loud before revealing it. “Again” returns in 1 minute; other ratings schedule the next review for 1 day or later. Your schedule is saved on this device.</div></div>`;
}
function renderReview(){if(review.index>=review.cards.length){const count=review.cards.length;main.innerHTML=`<div class="review-shell panel completion"><div class="big-icon">✳</div><p class="eyebrow">A LITTLE STRONGER THAN BEFORE</p><h1>Those words are going places.</h1><p>${count} cards reviewed. Your next reviews are scheduled.</p><a class="btn primary" href="#practice">Say something out loud ${icon('arrow')}</a>${action('Back to review','review-home','secondary')}<p class="center-note">If you chose Again, that card becomes due after 1 minute.</p></div>`;return;}
 const p=review.cards[review.index],prompt=review.direction==='es'?p.es:p.en,answer=review.direction==='es'?p.en:p.es;
 main.innerHTML=`<div class="review-shell">${heading('Make it stick.','','YOUR DAILY REVIEW')}<div class="review-controls"><span>Card ${review.index+1} / ${review.cards.length}</span><div class="toggle-group"><button class="toggle ${review.direction==='en'?'active':''}" data-action="review-direction" data-value="en">English → Spanish</button><button class="toggle ${review.direction==='es'?'active':''}" data-action="review-direction" data-value="es">Spanish → English</button></div></div><div class="progress-track" style="margin-bottom:20px"><span style="width:${review.index/review.cards.length*100}%"></span></div><section class="review-card"><p class="eyebrow">${esc(p.category)} · ${review.direction==='en'?'SAY IT IN SPANISH':'WHAT DOES THIS MEAN?'}</p><h2 ${review.direction==='es'?'lang="es-MX"':''}>${esc(prompt)}</h2>${review.flipped?`<p class="translation" ${review.direction==='en'?'lang="es-MX"':''}>${esc(answer)}</p>${sound(p.es)}${p.note?`<p class="review-note">${esc(p.note)}</p>`:''}`:`${action('Reveal answer','flip-review','primary reveal')}`}</section>${review.flipped?`<div class="ratings">${[['again','Again'],['hard','Hard'],['good','Got it'],['easy','Easy']].map(([grade,title])=>{const next=schedule(state.cards[p.id],grade);return `<button class="rating" data-action="rate-review" data-grade="${grade}">${title}<small>${grade==='again'?'1 min':next.interval+' day'+(next.interval===1?'':'s')}</small></button>`;}).join('')}</div>`:'<p class="center-note" style="margin-top:23px">Pause, remember, say it. Then reveal.</p>'}<p class="center-note">Use the audio to compare your pronunciation with your selected voice.</p><div data-voice-status></div></div>`;updateVoiceStatus();}
function practicePage(){speechResult=null;const p=phrases[speakIndex%phrases.length];
 main.innerHTML=heading('Find your Spanish voice.', 'Listen closely. Repeat it. Try a small conversation.','PRACTICE FOR THE REAL THING')+`<div class="practice-tabs"><button class="btn active" data-action="practice-home">${icon('mic')} Listen & repeat</button><button class="btn secondary" data-action="show-scenarios">${icon('chat')} Travel conversations</button></div><div class="speaking-layout"><div><div class="panel speaking-card"><p class="eyebrow">${esc(p.category)} · LISTEN, THEN REPEAT</p><h2 lang="es-MX">${esc(p.es)}</h2><p>${esc(p.en)}</p><div class="listen-actions">${listenButton(p.es,false,'Listen')}${listenButton(p.es,true,'Slower')}</div><button class="microphone" data-action="start-speech" aria-label="Start speech recognition" ${Recognition?'':'disabled'}>${icon('mic')}</button><p class="mic-caption" id="mic-caption">${Recognition?'Tap the mic, then say the Spanish phrase.':'Speech recognition is unavailable. Record yourself or practice aloud below.'}</p><div id="speech-result"></div><div class="button-row" style="justify-content:center">${action(icon('mic')+' Record & replay','record-audio','secondary small')}${action('I practiced aloud '+icon('check'),'mark-spoken','secondary small')}${action('Next phrase '+icon('arrow'),'next-speech','secondary small')}</div><div id="recording-result"></div><div class="typed-practice"><label for="typed-practice">Prefer typing? Type the Spanish from memory.</label><div class="input-row"><input id="typed-practice" lang="es-MX" autocomplete="off" placeholder="Escribe aquí…"><button class="btn secondary small" data-action="check-typed">Check</button></div></div></div><div data-voice-status></div><p class="speech-privacy">Microphone access is requested only when you tap a recording control. Browser speech recognition may send audio to its provider and require internet. Record & replay stays in memory on this device and is cleared when you leave. Word matching is a practice aid, not an accent assessment.</p></div><aside class="panel"><h2>The sound of Mexico</h2><div class="speaking-tips">${pronunciation.slice(0,3).map(p=>`<div class="tip-card"><h3>${esc(p.title)}</h3><p>${esc(p.tip)}</p><div class="tip-example"><span lang="es-MX">${esc(p.es)}</span>${sound(p.es)}</div></div>`).join('')}</div><details class="source-note"><summary>More pronunciation tips</summary>${pronunciation.slice(3).map(p=>`<div class="tip-card"><h3>${esc(p.title)}</h3><p>${esc(p.tip)}</p><div class="tip-example"><span lang="es-MX">${esc(p.es)}</span>${sound(p.es)}</div></div>`).join('')}</details></aside></div>`;updateVoiceStatus();}
function speakingCredit(id){const key=dayKey()+id;if(!sessionSpoken.has(key)){sessionSpoken.add(key);state.speaking++;logActivity(state,5,1);save();}}
function compareResult(text,typed=false){const p=phrases[speakIndex%phrases.length],score=compareSpeech(p.es,text);speechResult={score,text};const good=score>=80;if(good&&!typed)speakingCredit(p.id);
 $('#speech-result').innerHTML=`<div class="speech-result" role="status"><strong>${good?'¡Muy bien! Your words matched.':'A good start. Listen once more and try again.'}</strong><p>${typed?'You typed':'Your browser heard'}: “${esc(text)}”</p><p>Word match: ${score}%. ${typed?'This checks text recall.':'This compares the transcript, not your accent.'}</p></div>`;}
function startSpeech(targetId='practice'){
 if(!Recognition){toast('Use Record & replay, or practice aloud in this browser.');return;}
 if(recognition){recognition.stop();return;}
 if(recording?.state==='recording'){toast('Stop your replay recording first.');return;}
 window.speechSynthesis?.cancel();
 const r=new Recognition();recognition=r;r.lang='es-MX';r.interimResults=false;r.maxAlternatives=3;r.continuous=false;
 const mic=targetId==='practice'?$('[data-action="start-speech"]'):$('[data-action="scenario-speech"]');mic?.classList.add('recording');if(targetId==='practice')$('#mic-caption').textContent='Listening… tap again to stop.';else if($('#scenario-status'))$('#scenario-status').textContent='Listening…';
 r.onresult=e=>{const text=e.results[0][0].transcript;if(targetId==='practice')compareResult(text);else{const input=$('#scenario-input');if(input)input.value=text;checkScenario(text,true);}};
 r.onerror=e=>{const messages={'not-allowed':'Microphone access was denied. Allow it in your browser settings, or use typed practice.','no-speech':'No speech was detected. Try again in a quieter spot.','network':'Speech recognition needs a working connection. Try Record & replay instead.','audio-capture':'No microphone was found. Try typed practice.','language-not-supported':'Your browser does not support es-MX recognition. Try typed practice.'};const msg=messages[e.error]||'Speech recognition stopped. Try again or type your answer.';if(targetId==='practice')$('#mic-caption')&&( $('#mic-caption').textContent=msg);else if($('#scenario-status'))$('#scenario-status').textContent=msg;};
 r.onend=()=>{if(recognition===r)recognition=null;mic?.classList.remove('recording');if(targetId==='practice'&&$('#mic-caption')?.textContent.startsWith('Listening'))$('#mic-caption').textContent='Tap the mic to try again.';};
 try{r.start();}catch{recognition=null;mic?.classList.remove('recording');toast('Could not start speech recognition. Use typed practice or record & replay.');}
}
async function recordAudio(){
 if(recording?.state==='recording'){recording.stop();return;}
 if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){toast('Recording is unavailable. Try a supported browser on HTTPS or localhost.');return;}
 if(recognition){recognition.abort();recognition=null;}
 window.speechSynthesis?.cancel();
 try{
 const stream=await navigator.mediaDevices.getUserMedia({audio:true});
 if(route!=='practice'){stream.getTracks().forEach(t=>t.stop());return;}
 recordStream=stream;const chunks=[];const recorder=new MediaRecorder(stream);recording=recorder;const button=$('[data-action="record-audio"]');button.innerHTML=icon('stop')+' Stop recording';button.classList.add('recording');
 recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};
 recorder.onstop=()=>{clearTimeout(recordTimeout);stream.getTracks().forEach(t=>t.stop());recordStream=null;recording=null;if(route!=='practice')return;if(recordUrl)URL.revokeObjectURL(recordUrl);const blob=new Blob(chunks,{type:recorder.mimeType});recordUrl=URL.createObjectURL(blob);const box=$('#recording-result');if(box)box.innerHTML=`<p class="center-note">Your recording — listen, compare, try again.</p><audio controls src="${recordUrl}" style="width:100%;margin-top:10px"></audio>`;if(button?.isConnected){button.innerHTML=icon('mic')+' Record again';button.classList.remove('recording');}};
 recorder.start();recordTimeout=setTimeout(()=>{if(recorder.state==='recording')recorder.stop();},15000);
 }catch{recordStream?.getTracks().forEach(t=>t.stop());recordStream=null;toast('Microphone access is unavailable. Check browser permissions, or practice aloud.');}
}
function scenariosPage(){main.innerHTML=heading('A little practice. A real adventure.', 'Try the conversations you’ll actually have in Mexico.','TRAVEL CONVERSATIONS')+`<div class="practice-tabs"><button class="btn secondary" data-action="practice-home">${icon('mic')} Listen & repeat</button><button class="btn active" data-action="show-scenarios">${icon('chat')} Travel conversations</button></div><div class="scenario-grid">${scenarios.map(s=>`<a href="#scenario/${s.id}" class="scenario-card"><div class="scenario-icon">${s.icon}</div><p class="eyebrow">${esc(s.level)} ${state.scenarios.includes(s.id)?'· PRACTICED':''}</p><h2>${esc(s.title)}</h2><p>${esc(s.subtitle)}</p><span class="text-link">Step into the conversation ${icon('arrow')}</span></a>`).join('')}</div><div class="notice">These are guided role plays with model replies. Listen to each person, then say or type your response. You can reveal a hint whenever you need one.</div>`;}
function scenarioPage(id){const scenario=scenarios.find(s=>s.id===id);if(!scenario){location.hash='practice';return;}if(!scenarioSession||scenarioSession.id!==id)scenarioSession={id,step:0,hint:false,checked:false,matched:false};renderScenario();}
function renderScenario(){const s=scenarios.find(s=>s.id===scenarioSession.id),pair=scenarioSession.step*2,local=s.turns[pair],you=s.turns[pair+1];
 if(!local||!you){if(!state.scenarios.includes(s.id)){state.scenarios.push(s.id);logActivity(state,20,3);save();}main.innerHTML=`<div class="conversation panel completion"><div class="big-icon">${s.icon}</div><p class="eyebrow">CONVERSATION PRACTICED</p><h1>A little more ready for the real thing.</h1><p>You made it through “${esc(s.title)}”. Practice again any time.</p><a class="btn primary" href="#practice">Keep practicing ${icon('arrow')}</a>${action('Try this conversation again','restart-scenario','secondary')}</div>`;return;}
 main.innerHTML=`<div class="conversation"><a href="#practice" class="text-link back-link">${icon('back')} Practice</a>${heading(esc(s.title),esc(s.subtitle),'TRAVEL CONVERSATION')}<div class="quiz-progress"><span>Exchange ${scenarioSession.step+1} / ${s.turns.length/2}</span><div class="progress-track"><span style="width:${pair/s.turns.length*100}%"></span></div></div>${s.turns.slice(0,pair).map(t=>`<div class="chat-turn ${t.speaker==='you'?'you':''}"><div class="chat-label">${t.speaker==='you'?'YOU':'YOUR CONVERSATION PARTNER'}</div><div class="chat-line"><strong lang="es-MX">${esc(t.es)}</strong>${sound(t.es)}</div><p>${esc(t.en)}</p></div>`).join('')}<div class="chat-turn"><div class="chat-label">YOUR CONVERSATION PARTNER</div><div class="chat-line"><strong lang="es-MX">${esc(local.es)}</strong>${sound(local.es)}</div><p>${esc(local.en)}</p></div><div class="chat-turn you"><div class="chat-label">YOUR TURN · SAY THIS IN SPANISH</div><strong>${esc(you.en)}</strong>${scenarioSession.hint?`<p lang="es-MX">Model reply: ${esc(you.es)}</p>${sound(you.es)}`:''}<div class="input-row"><input id="scenario-input" lang="es-MX" placeholder="Tu respuesta…" autocomplete="off" aria-label="Your reply in Spanish"><button class="btn secondary small" data-action="scenario-speech" ${Recognition?'':'disabled'} aria-label="Say your reply">${icon('mic')}</button>${action('Check reply','check-scenario','primary small')}</div><div id="scenario-status" class="small-status" role="status"></div></div><div class="chat-actions">${action('Show model reply','scenario-hint','secondary small')}${action(scenarioSession.step===s.turns.length/2-1?'Finish conversation '+icon('check'):'Next exchange '+icon('arrow'),'scenario-next','primary small',scenarioSession.checked?'':'disabled')}</div><p class="speech-privacy">Microphone recognition uses es-MX and may send audio to your browser’s provider. Replies are compared with model sentences. Different natural wording may also be correct.</p><div data-voice-status></div></div>`;updateVoiceStatus();}
function checkScenario(text,fromMic=false){const s=scenarios.find(s=>s.id===scenarioSession.id),t=s.turns[scenarioSession.step*2+1],score=Math.max(...[t.es,...(t.alternatives||[])].map(x=>compareSpeech(x,text)));if(!text.trim()){toast('Say or type a reply first.');return;}
 const status=$('#scenario-status');status.textContent=score>=75?'¡Muy bien! Your reply matches the model.':`Your words differ from the model (${score}% word match). Other replies can be valid. Reveal the model and compare, then continue.`;scenarioSession.checked=true;scenarioSession.matched=score>=75;$('[data-action="scenario-next"]').disabled=false;if(score>=75&&fromMic)speakingCredit(s.id+scenarioSession.step);}
function progressPage(){const pts=totalPoints(),minutes=todayMinutes(),percent=Math.min(100,minutes/state.settings.goal*100),count=completedCount(),seen=reviewedCount(),cards=Object.values(state.cards);const now=new Date();const days=Array.from({length:7},(_,i)=>{const d=new Date(now.getFullYear(),now.getMonth(),now.getDate()-6+i,12);return {key:dayKey(d),label:d.toLocaleDateString('en',{weekday:'short'}),points:state.activity[dayKey(d)]?.points||0};});const max=Math.max(10,...days.map(d=>d.points));
 main.innerHTML=heading('Look how far you’re going.', 'Every little conversation begins with a little practice.','YOUR PROGRESS',tripChip())+`<div class="stats-row"><div class="stat"><span class="stat-icon">${icon('flame')}</span><div><strong>${streak(state.activity)} ${streak(state.activity)===1?'day':'days'}</strong><small>Current streak</small></div></div><div class="stat"><span class="stat-icon">${icon('spark')}</span><div><strong>${pts}</strong><small>Practice points earned</small></div></div><div class="stat"><span class="stat-icon">${icon('mic')}</span><div><strong>${state.speaking}</strong><small>Speaking practices logged</small></div></div></div><div class="progress-grid"><div><section class="panel"><h2>This week, in small steps</h2><p>Practice points per day. Today’s activity counts toward your streak.</p><div class="activity-week" role="img" aria-label="${esc(days.map(d=>d.label+': '+d.points+' points').join(', '))}">${days.map((d,i)=>`<div class="activity-day ${i===6?'today':''}"><span class="points">${d.points}</span><span class="activity-bar" style="height:${Math.max(4,d.points/max*100)}px"></span><span>${d.label}</span></div>`).join('')}</div></section><section class="panel"><h2>Your travel toolkit</h2><div class="mini-stat-row"><span>Grammar lessons completed</span><strong>${count} / ${lessons.length}</strong></div><div class="mini-stat-row"><span>Distinct phrases reviewed</span><strong>${seen} / ${phrases.length}</strong></div><div class="mini-stat-row"><span>Cards with a 7+ day review interval</span><strong>${cards.filter(c=>c.interval>=7).length}</strong></div><div class="mini-stat-row"><span>Travel conversations practiced</span><strong>${state.scenarios.length} / ${scenarios.length}</strong></div><p class="source-note">Progress measures your activity, not a fluency level. Speaking counts include successful word matches and practice you mark yourself.</p></section></div><div><section class="panel"><h2>Today’s little goal</h2><div class="goal-box"><span>Estimated practice minutes</span><strong>${Math.round(minutes)} / ${state.settings.goal}</strong></div><div class="progress-track"><span style="width:${percent}%"></span></div><p class="goal-label">Minutes are estimates from completed activities. ${percent>=100?'Goal reached. ¡Bien hecho!':'A few focused minutes can go a long way.'}</p><a class="text-link" href="#today">Keep going ${icon('arrow')}</a></section><section class="panel"><h2>Your road to February</h2>${phases.map((p,i)=>`<div class="phase"><span class="phase-num">${i+1}</span><div><small>${esc(p.when)}</small><h3>${esc(p.title)}</h3><p>${esc(p.focus)}</p></div></div>`).join('')}</section></div></div>`;}
function settingsPage(){main.innerHTML=heading('Make this journey yours.', 'Your trip, your pace, your Spanish voice.','SETTINGS & AUDIO')+`<div class="settings-grid"><div><section class="panel"><h2>The journey ahead</h2><div class="form-field"><label for="trip-date">Your departure date</label><input type="date" id="trip-date" value="${state.settings.trip}" min="2026-01-01" max="2040-12-31"><small>Set to February 1, 2027 until you know your exact travel date.</small></div><div class="form-field"><label for="daily-goal">Daily practice goal</label><select id="daily-goal">${[5,10,15,20,30].map(n=>`<option value="${n}" ${state.settings.goal===n?'selected':''}>${n} minutes a day</option>`).join('')}</select><small>Aim for a lesson, a few review cards, and a little speaking practice.</small></div></section><section class="panel"><h2>Your listening voice</h2><p>Rumbo uses your device’s text to speech. A voice labeled <strong>es-MX</strong> is preferred for a Mexican accent.</p><div class="form-field"><label for="voice-select">Spanish voice</label><select id="voice-select"></select></div><div data-voice-status></div><div class="form-field"><label for="speech-rate">Playback speed</label><div class="range-row"><input type="range" id="speech-rate" min="0.6" max="1.1" step="0.05" value="${state.settings.rate}"><output id="speed-value">${state.settings.rate.toFixed(2)}×</output></div></div>${listenButton('Hola. ¿Me trae la cuenta, por favor?',false,'Test my voice')}<details><summary>Add a Mexican Spanish voice</summary><p>On iPhone or iPad, look in Settings → Accessibility → Spoken Content (or Read & Speak) → Voices → Spanish → Mexico. On macOS, look in System Settings → Accessibility → Spoken Content or Read & Speak → System voice → Manage voices. Download a Mexican Spanish voice, then reopen Rumbo.</p><p>On Android or Windows, search your device settings for “Text to speech” or “Speech voices” and add Spanish (Mexico). Exact names vary by device. Your browser must expose the installed voice.</p><p>If you deliberately select another Spanish voice, the app displays its language. It will not label that voice Mexican.</p></details></section></div><div><section class="panel install-panel"><h2>A little Spanish in your pocket</h2><p>Add Rumbo to your home screen for quick practice on the go.</p>${action(icon('download')+' Install Rumbo','install','primary')}<div id="offline-status" class="source-note">Checking offline availability…</div><p class="source-note">Lessons, phrasebook, review, and progress can work offline after the first complete load. Audio depends on locally downloaded voices. Browser speech recognition may need internet.</p></section><section class="panel"><h2>Keep your progress</h2><p>Your lessons and review schedule are saved only in this browser on this device. Export a backup to move them to another device or protect against cleared browser storage.</p><div class="button-row">${action(icon('download')+' Export backup','export-progress','secondary small')}${action('Import backup','import-progress','secondary small')}</div><input type="file" id="import-file" accept="application/json,.json" hidden><div id="import-confirm"></div><details><summary>Start fresh</summary><p>This removes your saved progress and settings from this browser.</p>${action('Reset progress…','reset-request','secondary small danger')}<div id="reset-confirm"></div></details></section><section class="panel"><h2>With thanks to Trinia</h2><p>Trinia shared the initial <em>Gramática básica del español</em> document that inspired Rumbo. Thank you for helping start this learning journey.</p><p>Core lessons follow the guide’s basic questions, introductions, activities, places, and more grammar. Travel phrases, dialogues, and pronunciation practice extend the guide.</p><p>Use this as a daily practice companion. Short, regular listening and real conversations will help you prepare for Mexico.</p><a href="#progress" class="text-link">See your learning progress ${icon('arrow')}</a></section></div></div>`;renderVoiceOptions();updateVoiceStatus();updateOfflineStatus();}
function renderVoiceOptions(){const select=$('#voice-select');if(!select)return;const all=voiceList(),chosen=selectedVoice();select.innerHTML=`<option value="">Automatic · prefer Spanish (Mexico)</option>`+all.sort((a,b)=>Number(mexicanVoice(b))-Number(mexicanVoice(a))).map(v=>`<option value="${esc(v.voiceURI)}" ${state.settings.voice===v.voiceURI?'selected':''}>${esc(v.name)} · ${esc(v.lang)}${mexicanVoice(v)?' · Mexico':''}${v.localService?' · on device':''}</option>`).join('');if(!all.length)select.innerHTML='<option value="">No Spanish voices available yet</option>';}
async function updateOfflineStatus(){const n=$('#offline-status');if(!n)return;if(!('serviceWorker'in navigator)){n.textContent='Offline storage is unavailable in this browser.';return;}try{const reg=await navigator.serviceWorker.getRegistration();n.textContent=reg?.active?'Offline app files are ready on this device.':'Offline files are preparing. Keep this page open briefly, then refresh.';}catch{n.textContent='Offline status could not be checked.';}}
function exportProgress(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`rumbo-progress-${dayKey()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);toast('Backup exported. Keep it somewhere safe.');}
let pendingImport=null;
async function importProgress(file){if(!file)return;if(file.size>2*1024*1024){toast('Choose a Rumbo JSON backup smaller than 2 MB.');return;}try{pendingImport=validateState(JSON.parse(await file.text()));$('#import-confirm').innerHTML=`<div class="danger-box">Replace this device’s progress with the backup? It contains ${Object.keys(pendingImport.completed).length} completed lessons and ${Object.keys(pendingImport.cards).length} reviewed phrases.<div class="button-row">${action('Use this backup','confirm-import','primary small')}${action('Cancel','cancel-import','secondary small')}</div></div>`;}catch{pendingImport=null;toast('Could not read this backup. Choose a valid Rumbo JSON export.');}}
function showInstall(){if(installPrompt){installPrompt.prompt();installPrompt.userChoice.then(()=>installPrompt=null);return;}$('#help-content').innerHTML='<ol><li><strong>iPhone or iPad:</strong> open Rumbo in Safari, tap Share, then Add to Home Screen.</li><li><strong>Android:</strong> open Rumbo in Chrome, tap the menu, then Install app or Add to Home screen.</li><li><strong>Computer:</strong> look for the install button in your browser’s address bar or menu.</li></ol><p>Install options depend on your browser. A home-screen bookmark also makes practice easy.</p>';$('#help-dialog').showModal();}
function cleanup(){recognition?.abort();recognition=null;clearTimeout(recordTimeout);if(recording?.state==='recording'){recording.onstop=null;recording.stop();}recording=null;recordStream?.getTracks().forEach(t=>t.stop());recordStream=null;if(recordUrl){URL.revokeObjectURL(recordUrl);recordUrl='';}window.speechSynthesis?.cancel();}
function navigate(){cleanup();quiz=null;review=null;const parts=location.hash.replace(/^#\/?/,'').split('/');route=parts[0]||'today';sub=parts[1]||'';if(route!=='scenario')scenarioSession=null;
 const render={today:todayPage,lessons:lessonsPage,phrases:phrasePage,review:reviewPage,practice:practicePage,progress:progressPage,settings:settingsPage};if(route==='lesson')lessonPage(sub);else if(route==='scenario')scenarioPage(sub);else if(render[route]){if(route==='practice'&&sub){const index=phrases.findIndex(p=>p.id===sub);if(index>=0)speakIndex=index;}render[route]();}else{location.hash='today';return;}
 document.title=`${route==='today'?'Rumbo':route==='lesson'?'Lesson':route==='scenario'?'Conversation':nav.find(n=>n[0]===route)?.[2]||'Settings'} · Spanish for Mexico`;updateChrome();window.scrollTo({top:0,behavior:'instant'});main.focus({preventScroll:true});}

// One event handler keeps controls usable after each view refresh.
document.addEventListener('click',async e=>{
 const link=e.target.closest('a[href^="#"]');if(link?.classList.contains('skip')){e.preventDefault();main.focus();return;}if(link&&link.hash===location.hash){e.preventDefault();navigate();return;}
 const btn=e.target.closest('[data-say],[data-action]');if(!btn||btn.disabled)return;
 if(btn.dataset.say){say(decodeURIComponent(btn.dataset.say),btn.dataset.slow==='true',btn);return;}
 const a=btn.dataset.action;
 if(a==='start-quiz'){quiz={id:btn.dataset.id,index:0,score:0,choice:null};renderQuiz();}
 else if(a==='quiz-answer'&&quiz&&quiz.choice===null){quiz.choice=Number(btn.dataset.index);const l=lessons.find(l=>l.id===quiz.id);if(quiz.choice===l.questions[quiz.index].answer)quiz.score++;renderQuiz();}
 else if(a==='quiz-next'&&quiz){quiz.index++;quiz.choice=null;renderQuiz();}
 else if(a==='start-review'){review={cards:dueCards(phrases,state).slice(0,10),index:0,flipped:false,direction:'en'};renderReview();}
 else if(a==='flip-review'&&review){review.flipped=true;renderReview();}
 else if(a==='review-direction'&&review){review.direction=btn.dataset.value;review.flipped=false;renderReview();}
 else if(a==='rate-review'&&review?.flipped){const p=review.cards[review.index];state.cards[p.id]=schedule(state.cards[p.id],btn.dataset.grade);logActivity(state,3,.5,true);save();review.index++;review.flipped=false;renderReview();}
 else if(a==='review-home'){review=null;reviewPage();}
 else if(a==='start-speech')startSpeech();
 else if(a==='next-speech'){cleanup();speakIndex=(speakIndex+1)%phrases.length;practicePage();}
 else if(a==='check-typed'){const text=$('#typed-practice').value.trim();if(text)compareResult(text,true);else toast('Type the Spanish phrase first.');}
 else if(a==='mark-spoken'){speakingCredit(phrases[speakIndex%phrases.length].id);toast('Speaking practice logged. ¡Sigue así!');}
 else if(a==='record-audio')await recordAudio();
 else if(a==='practice-home'){cleanup();practicePage();}
 else if(a==='show-scenarios'){cleanup();scenariosPage();}
 else if(a==='scenario-speech')startSpeech('scenario');
 else if(a==='check-scenario')checkScenario($('#scenario-input').value);
 else if(a==='scenario-hint'){scenarioSession.hint=true;scenarioSession.checked=true;renderScenario();}
 else if(a==='scenario-next'&&scenarioSession?.checked){cleanup();scenarioSession.step++;scenarioSession.hint=false;scenarioSession.checked=false;renderScenario();window.scrollTo({top:document.body.scrollHeight,behavior:'smooth'});}
 else if(a==='restart-scenario'){scenarioSession.step=0;scenarioSession.hint=false;scenarioSession.checked=false;renderScenario();}
 else if(a==='export-progress')exportProgress();
 else if(a==='import-progress')$('#import-file').click();
 else if(a==='confirm-import'&&pendingImport){state=pendingImport;pendingImport=null;save();settingsPage();toast('Backup imported. Your journey continues.');}
 else if(a==='cancel-import'){pendingImport=null;$('#import-confirm').innerHTML='';}
 else if(a==='reset-request')$('#reset-confirm').innerHTML=`<div class="danger-box">Clear all lessons, reviews, and settings on this device?<div class="button-row">${action('Yes, clear my progress','reset-confirm','secondary small danger')}${action('Cancel','cancel-reset','secondary small')}</div></div>`;
 else if(a==='cancel-reset')$('#reset-confirm').innerHTML='';
 else if(a==='reset-confirm'){state=initialState();sessionSpoken.clear();save();settingsPage();toast('Progress reset on this device.');}
 else if(a==='install')showInstall();
 else if(a==='close-help')$('#help-dialog').close();
});
document.addEventListener('input',e=>{if(e.target.id==='phrase-search')filterPhrases();if(e.target.id==='speech-rate'){state.settings.rate=Number(e.target.value);$('#speed-value').textContent=state.settings.rate.toFixed(2)+'×';save();}});
document.addEventListener('change',e=>{const t=e.target;if(t.id==='phrase-category')filterPhrases();else if(t.id==='trip-date'){if(!validDay(t.value)||t.value<'2026-01-01'||t.value>'2040-12-31'){toast('Choose a valid departure date.');t.value=state.settings.trip;return;}state.settings.trip=t.value;save();}else if(t.id==='daily-goal'){state.settings.goal=Number(t.value);save();}else if(t.id==='voice-select'){state.settings.voice=t.value;save();updateVoiceStatus();}else if(t.id==='import-file')importProgress(t.files?.[0]);});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.id==='typed-practice')$('[data-action="check-typed"]').click();if(e.key==='Enter'&&e.target.id==='scenario-input')$('[data-action="check-scenario"]').click();});
window.addEventListener('hashchange',navigate);window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;});window.addEventListener('pagehide',cleanup);
window.addEventListener('offline',()=>toast('You’re offline. Lessons and reviews stay with you. Audio support depends on your device.'));
window.speechSynthesis?.addEventListener('voiceschanged',loadVoices);
loadVoices();navigate();
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').then(reg=>{if(reg.active)updateOfflineStatus();else reg.addEventListener('updatefound',()=>{reg.installing?.addEventListener('statechange',updateOfflineStatus);});}).catch(()=>{if(route==='settings')$('#offline-status').textContent='Offline files could not be installed. Use HTTPS or localhost and try reloading.';});
